import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    c1 = int(data[1])
    c2 = int(data[2])
    s = data[3].strip()

    INF = 10**30
    dp = [INF] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == INF:
            continue
        # form groups starting at i
        adults = 0
        for j in range(i, n):
            if s[j] == '1':
                adults += 1
            if adults == 0:
                continue
            x = j - i + 1
            cost = c1 + c2 * (x - 1) * (x - 1)
            if dp[i] + cost < dp[j + 1]:
                dp[j + 1] = dp[i] + cost

    print(dp[n])

if __name__ == "__main__":
    main()
